sp_widget.css:
/* ==============================
   CFMS GLOBAL
================================ */

.cfms-home {
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
  color: #102b3a;
  background: #ffffff;
  margin: 0;
}


/* ==============================
   HEADER
================================ */

.cfms-header {
  height: 76px;
  background: #ffffff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 5.5%;

  box-shadow: 0 1px 8px rgba(0,0,0,0.08);

  position: relative;
  z-index: 10;
}


.cfms-logo-area {
  display: flex;
  align-items: center;
  gap: 14px;
}


.cfms-logo-icon {
  font-size: 38px;
  color: #008f83;
}


.cfms-logo {
  font-size: 29px;
  font-weight: 800;
  color: #102b3a;
  line-height: 1;
}


.cfms-subtitle {
  font-size: 14px;
  font-weight: 600;
  color: #102b3a;
  margin-top: 3px;
}


.cfms-nav {
  display: flex;
  align-items: center;
  gap: 38px;
}


.cfms-nav a {
  text-decoration: none;
  color: #243746;
  font-size: 15px;
  font-weight: 500;

  position: relative;

  padding: 28px 0;
}


.cfms-nav a.active {
  color: #008f83;
}


.cfms-nav a.active::after {
  content: "";

  position: absolute;

  bottom: 12px;
  left: 0;
  right: 0;

  height: 2px;

  background: #008f83;
}


.login-button {
  background: #078b80 !important;
  color: white !important;

  padding: 12px 28px !important;

  border-radius: 8px;

  font-weight: 700 !important;
}


/* ==============================
   HERO
================================ */

.cfms-hero {
  min-height: 375px;

  position: relative;

  background-image:
    url("/cfms-cafeteria.jpg");

  background-size: cover;
  background-position: center;
}


.hero-overlay {
  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      90deg,
      rgba(4, 25, 35, 0.90),
      rgba(4, 25, 35, 0.68),
      rgba(4, 25, 35, 0.45)
    );
}


.hero-content {
  position: relative;
  z-index: 2;

  display: flex;
  justify-content: space-between;
  align-items: center;

  padding: 32px 5.7% 26px;

  gap: 50px;
}


.hero-left {
  max-width: 700px;
}


.hero-left h1 {
  color: #ffffff;

  font-size: 52px;
  line-height: 1.08;

  margin: 25px 0 18px;

  font-weight: 800;
}


.hero-left p {
  color: #ffffff;

  font-size: 18px;
  line-height: 1.55;

  max-width: 650px;

  margin-bottom: 25px;
}


.get-started {
  display: inline-flex;

  align-items: center;
  gap: 20px;

  background: #08b5a5;

  color: #ffffff;

  text-decoration: none;

  padding: 14px 27px;

  border-radius: 28px;

  font-size: 16px;
  font-weight: 700;
}


.get-started span {
  font-size: 25px;
}


/* ==============================
   LOGIN PANEL
================================ */

.login-panel {
  background: #ffffff;

  width: 380px;

  padding: 25px;

  border-radius: 9px;

  box-shadow:
    0 10px 35px rgba(0,0,0,0.25);
}


.login-panel h2 {
  margin: 0;

  font-size: 22px;
}


.login-description {
  margin: 6px 0 14px;

  color: #607180;

  font-size: 14px;
}


.login-card {
  display: flex;

  align-items: center;

  gap: 13px;

  text-decoration: none;

  color: #102b3a;

  border: 1px solid #d8e0e5;

  border-radius: 8px;

  padding: 10px;

  margin-top: 9px;

  transition: 0.2s;
}


.login-card:hover {
  transform: translateX(3px);

  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
}


.login-icon {
  width: 40px;
  height: 40px;

  border-radius: 8px;

  display: flex;

  align-items: center;
  justify-content: center;

  font-size: 20px;
}


.login-icon.student {
  background: #4169e1;
}


.login-icon.officer {
  background: #079228;
}


.login-icon.admin {
  background: #8051d9;
}


.login-info {
  display: flex;

  flex-direction: column;

  flex: 1;
}


.login-info strong {
  font-size: 15px;
}


.login-info span {
  color: #647481;

  font-size: 12px;

  margin-top: 3px;
}


.arrow {
  font-size: 27px;

  color: #008f83;
}


/* ==============================
   FEATURE CARDS
================================ */

.feature-section {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 20px;

  padding: 22px 5.7%;
}


.feature-card {
  display: flex;

  align-items: center;

  gap: 17px;

  background: #ffffff;

  padding: 18px;

  border-radius: 9px;

  box-shadow:
    0 3px 15px rgba(0,0,0,0.08);
}


.feature-icon {
  min-width: 55px;
  height: 55px;

  border-radius: 50%;

  display: flex;

  align-items: center;
  justify-content: center;

  color: white;

  font-size: 24px;
}


.feature-icon.green {
  background: #0fa48d;
}


.feature-icon.blue {
  background: #2588cf;
}


.feature-icon.orange {
  background: #f2a400;
}


.feature-icon.red {
  background: #e94b50;
}


.feature-card h3 {
  margin: 0 0 7px;

  font-size: 16px;
}


.feature-card p {
  margin: 0;

  color: #526474;

  font-size: 13px;

  line-height: 1.5;
}


/* ==============================
   ABOUT
================================ */

.about-section {
  display: grid;

  grid-template-columns: 1fr 1.15fr;

  gap: 50px;

  padding: 25px 5.7% 30px;
}


.about-left {
  border-right: 1px solid #dce5e9;

  padding-right: 45px;
}


.section-label {
  color: #008f83;

  font-size: 14px;

  font-weight: 700;

  margin-bottom: 12px;
}


.about-left h2 {
  font-size: 30px;

  line-height: 1.15;

  margin: 0 0 18px;
}


.about-left p {
  color: #526474;

  font-size: 15px;

  line-height: 1.6;
}


.learn-button {
  display: inline-flex;

  align-items: center;

  gap: 15px;

  border: 1px solid #008f83;

  color: #008f83;

  text-decoration: none;

  padding: 10px 24px;

  border-radius: 6px;

  font-weight: 700;
}


/* ==============================
   STATS
================================ */

.stats {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  text-align: center;

  gap: 15px;
}


.stat-icon {
  font-size: 27px;

  color: #008f83;

  margin-bottom: 8px;
}


.stat strong {
  display: block;

  font-size: 20px;

  margin-bottom: 5px;
}


.stat span {
  display: block;

  color: #526474;

  font-size: 13px;
}


/* ==============================
   QUOTE
================================ */

.quote {
  margin-top: 25px;

  background: #e4f7f2;

  border-radius: 10px;

  padding: 20px;

  text-align: center;
}


.quote-mark {
  color: #009b8d;

  font-size: 38px;

  height: 20px;
}


.quote p {
  font-size: 17px;

  font-style: italic;

  margin: 5px 0 15px;

  color: #36525d;
}


.quote span {
  font-size: 14px;
}


/* ==============================
   FOOTER
================================ */

.cfms-footer {
  background: #002f3e;

  color: white;

  display: grid;

  grid-template-columns:
    1.5fr 1fr 1.3fr 1fr;

  gap: 40px;

  padding: 35px 5.7%;
}


.footer-logo {
  font-size: 27px;

  font-weight: 800;
}


.footer-brand p {
  margin-top: 5px;

  font-size: 13px;
}


.footer-column {
  display: flex;

  flex-direction: column;

  gap: 9px;
}


.footer-column h4 {
  margin: 0 0 7px;

  font-size: 15px;
}


.footer-column a {
  color: #ffffff;

  text-decoration: none;

  font-size: 13px;
}


.footer-column p {
  margin: 0;

  font-size: 13px;

  color: #e4eef1;
}


.social-icons {
  font-size: 18px;

  margin-bottom: 10px;
}


/* ==============================
   RESPONSIVE
================================ */

@media (max-width: 1000px) {

  .cfms-nav {
    gap: 15px;
  }

  .hero-content {
    flex-direction: column;

    align-items: stretch;
  }

  .login-panel {
    width: auto;
  }

  .feature-section {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .about-section {
    grid-template-columns: 1fr;
  }

  .about-left {
    border-right: none;

    border-bottom: 1px solid #ddd;

    padding-right: 0;

    padding-bottom: 25px;
  }

}


@media (max-width: 650px) {

  .cfms-header {
    height: auto;

    padding: 15px;

    flex-direction: column;

    gap: 15px;
  }

  .cfms-nav {
    flex-wrap: wrap;

    justify-content: center;
  }

  .hero-left h1 {
    font-size: 38px;
  }

  .feature-section {
    grid-template-columns: 1fr;
  }

  .stats {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .cfms-footer {
    grid-template-columns: 1fr;
  }

}

sp_widget.script:
(function() {

    data.title = "Campus Food Management System";
    data.studentsServed = "1000+";
    data.menuUpdates = "Daily";
    data.issueResolution = "Quick";
    data.community = "Healthier";

})();
